const c = $json;
let inputs = {}; let assertions = [];
if (typeof c.inputs === 'object') { inputs = c.inputs; } else { try { inputs = JSON.parse(c.inputs || '{}'); } catch (e) { inputs = {}; } }
if (Array.isArray(c.assertions)) { assertions = c.assertions; } else { try { assertions = JSON.parse(c.assertions || '[]'); } catch (e) { assertions = []; } }
return { json: { run_id: c.run_id || '', test_case_id: c.id || '', case_id: c.case_id, target: c.target, agent: c.agent || '', description: c.description || '', inputs, assertions } };

const caseData = $('Parse Case').first().json;
const rows = $input.all().map((i) => i.json);
const details = [];
let status = 'pass';
function getPath(obj, path) { return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj); }
if (rows.length === 0) {
  status = 'error';
  details.push({ assertion: 'execution', pass: false, detail: 'Target returned no output items' });
} else if (rows[0] && rows[0].error) {
  status = 'error';
  details.push({ assertion: 'execution', pass: false, detail: JSON.stringify(rows[0].error).slice(0, 600) });
} else {
  for (const a of caseData.assertions) {
    let pass = false; let got;
    try {
      if (a.type === 'row_count') {
        got = rows.length;
        const v = Number(a.value);
        pass = a.op === '>=' ? got >= v : a.op === '<=' ? got <= v : got === v;
      } else if (a.type === 'field_exists') {
        got = getPath(rows[0], a.path);
        pass = got !== undefined && got !== null;
      } else if (a.type === 'contains') {
        got = '(substring search)';
        pass = JSON.stringify(rows).includes(a.value);
      } else if (a.type === 'exact') {
        got = a.path ? getPath(rows[0], a.path) : (rows.length === 1 ? rows[0] : rows);
        pass = JSON.stringify(got) === JSON.stringify(a.value);
      } else if (a.type === 'tool_called') {
        got = rows[0].tools_used || [];
        pass = got.includes(a.value);
      } else {
        status = 'fail';
        details.push({ assertion: String(a.type), pass: false, detail: 'unknown assertion type' });
        continue;
      }
    } catch (e) {
      status = 'fail';
      details.push({ assertion: String(a.type), pass: false, detail: String(e).slice(0, 300) });
      continue;
    }
    if (!pass) status = 'fail';
    details.push({ assertion: a.type + (a.path ? ' ' + a.path : ''), pass, expected: a.value, got: typeof got === 'string' ? got.slice(0, 200) : got });
  }
}
return [{ json: { run_id: caseData.run_id || '', case_id: caseData.case_id, target: caseData.target, status, actual_output: JSON.stringify(rows).slice(0, 3500), assertion_detail: JSON.stringify(details).slice(0, 3500) } }];

const d = $json;
const answer = (d.output ?? d.text ?? d.response ?? '').toString();
const steps = Array.isArray(d.intermediateSteps) ? d.intermediateSteps : [];
const tools = [...new Set(steps.map((s) => s && s.action && s.action.tool).filter(Boolean))];
return { json: { answer, tools_used: tools } };
